{
        // is there a system resource of character names per language?
        char buf[80];
        my_unique_identifier = 0;
        my_user_data = NULL;

        sprintf(buf, "<say-as interpret-as=\"tts:char\">&#%d;</say-as>", character);
        return Synthesize(0, buf, espeakSSML);
}

